llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Celiprolol, a structurally close aryloxypropanolamine beta-blocker with a para-ureido substituent and tert-butylamino side chain, has human oral bioavailability of 30–70%, supporting F ≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Tertatolol, a lipophilic aryloxypropanolamine beta-blocker, has absolute oral bioavailability of 64% (range 45–98%) in healthy volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Atenolol, a hydrophilic para-substituted aryloxypropanolamine, has oral bioavailability of 60–63% in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Pafenolol, a beta-blocker with a similar 4-substituted phenoxypropanolamine core, has systemic availability of 27.5% at a 40 mg oral solution dose, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Prenalterol, another close analogue, has absolute bioavailability of 27 ± 4% in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental evidence from structurally related beta-blockers shows oral bioavailability values above 20%, mostly 25–100%. The query is a talinolol-like aryloxypropanolamine with a cyclohexylurea substituent; rifampin co-treatment may reduce bioavailability through P-gp/CYP induction, but the high baseline F of close analogues makes a drop below 20% unlikely.",
  "evidence_gaps": [
    "No retrieved experimental record directly measures the query under rifampin co-treatment.",
    "The magnitude of rifampin-mediated reduction in oral bioavailability is inferred from pharmacology rather than direct evidence in the supplied records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

